@router.get("/api/v1/shards/{shard_key}/patients/{patient_record_id}")
def get_patient_on_shard(
    shard_key: str,
    patient_record_id: int,
    engine_registry: ShardEngineRegistry = Depends(get_shard_registry),
    current_user: User = Depends(get_current_user)
):
    if shard_key not in current_user.assigned_clinic_shards:
        raise HTTPException(status_code=403, detail="Access to requested hospital shard forbidden")
    shard_engine = engine_registry.get_engine_for_shard(shard_key)
    if not shard_engine:
        raise HTTPException(status_code=404, detail="Target shard does not exist")
    with Session(shard_engine) as session:
        patient = session.get(MedicalRecord, patient_record_id)
        if not patient:
            raise HTTPException(status_code=404, detail="Patient record not found on shard")
        return {"id": patient.id, "full_name": patient.full_name, "diagnosis": patient.medical_history}
